// TH15 th15_s1_w08: Stage 1 MainSub06 reward formation after the second midboss.
// Source: st01.ecl.txt:1109-1138 (entry), GirlC01 415-438, GirlC01_at 440-495.
// Chapter / -9905 / enmCreateF gating removed per task; the formation itself is kept.

const TIME_LIMIT: int = 2524;
const OPENING_BUFFER: int = 120;

const TH15_RICE: int = 480;
const RICE_COLOR: int = 6;

// GirlC01_at etAngle second arg 0.12217305 rad = 7 deg -> 1274 BAM.
const FAN_DELTA_BAM: int = 1274;

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

// MainSub06 spawn schedule: $A=4 do-while body (4 spawns, 80 frames apart),
// then one trailing spawn at -192 and wait(19).
async sub pattern() {
    wait(OPENING_BUFFER);
    for cycle in 0..4 {
        spawn_girl(-192fx);
        wait(80);
        spawn_girl(192fx);
        wait(80);
        spawn_girl(-256fx);
        wait(80);
        spawn_girl(256fx);
        wait(80);
    }
    spawn_girl(-192fx);
    wait(19);
}

// enmCreateF("GirlC01", x, -24.0f, 600, 1000, 1) with x = base + RANDF2*16.
sub spawn_girl(base: fx) {
    var signed_u: fx = (rand(65536) - 32768) as fx / 32768;
    var x: fx = base + 16fx * signed_u;
    _ = spawn_enemy(x, -24fx, 600, 0, 0, 0, girl(x));
}

// GirlC01: boxes kept (source setHurtbox(32,32) -> r16, setHitbox(24,24) -> r12),
// mirror applies to the side whose final x > 0, movement per moveVel/moveVelTime(80,1,...).
async sub girl(origin_x: fx) {
    set_invuln(65535);
    set_hurtbox(16fx);
    set_hitbox(12fx);
    var a0: angle = 8192bam;    // 45 deg
    var a1: angle = 4096bam;    // 22.5 deg
    if origin_x > 0fx {
        a0 = 24576bam;          // mirrored 135 deg
        a1 = 28672bam;          // mirrored 157.5 deg
    }
    move_vel(0, a0, 3fx, EASE_LINEAR);
    move_vel(80, a1, 1fx, EASE_QUAD_IN);
    spawn girl_at();
    wait(60);
    loop { wait(1000); }
}

// GirlC01_at: wait(60); single et slot, fixed-direction fan at 90 deg, 7 deg spacing,
// count 1/1/2/5 and B/C/A per difficulty. Outer B groups, inner C volleys.
async sub girl_at() {
    wait(60);
    var rank: int = global(GVAR_RANK);
    var count: int = 1;
    var inner_wait: int = 4;
    var post_wait: int = 60;
    var outer: int = 1;
    var inner: int = 6;
    var speed0: fx = 1fx;
    if rank == 1 {
        outer = 3;
        inner = 12;
        speed0 = 1.5fx;
    }
    if rank == 2 {
        count = 2;
        inner_wait = 2;
        post_wait = 30;
        outer = 6;
        inner = 12;
        speed0 = 2fx;
    }
    if rank == 3 {
        count = 5;
        inner_wait = 1;
        post_wait = 20;
        outer = 12;
        inner = 12;
        speed0 = 3fx;
    }
    var sp: fx = speed0;
    var b: int = outer;
    loop {
        var c: int = inner;
        loop {
            fan_fire(count, sp);
            sp = sp + 0.15fx;
            wait(inner_wait);
            c = c - 1;
            if c <= 0 { break; }
        }
        wait(post_wait);
        b = b - 1;
        if b <= 0 { break; }
        sp = speed0;
    }
}

// One etOn volley: TH15 type 8 rice, color 6, angles 90deg + F(N,i)*delta.
// EX ANIM a=1 birth displacement position -= 4*velocity is kept by spawning
// each bullet 4*speed back along its own firing angle.
sub fan_fire(n: int, sp: fx) {
    for i in 0..n {
        var off: int = ((i + 1) / 2) * FAN_DELTA_BAM;
        if n % 2 == 0 {
            off = (i / 2) * FAN_DELTA_BAM + FAN_DELTA_BAM / 2;
        }
        if i % 2 != 0 {
            off = -off;
        }
        var a: angle = 90deg + (off as angle);
        var bx: fx = $self_x - 4fx * sp * cos(a);
        var by: fx = $self_y - 4fx * sp * sin(a);
        _ = fire(TH15_RICE, RICE_COLOR, bx, by, sp, a, none, none);
    }
}
